import { TwoFactorStateError, type AdminAccount } from '@vfortin/identity-domain';
import {
  InvalidSessionError,
  TotpInvalidError,
} from '@internal/identity-application/lib/errors/application-error';
import type {
  Clock,
  IdentityUnitOfWork,
  TotpVerifier,
} from '@internal/identity-application/lib/ports/identity/identity.ports';

/**
 * Interface EnableTwoFactorCommand
 * @interface EnableTwoFactorCommand
 *
 * @description
 * Enrollment confirmation: a code generated by the authenticator from the pending secret.
 */
export interface EnableTwoFactorCommand {
  // #region Properties
  /**
   * Property accountId
   * @readonly
   *
   * @description
   * Subject of the verified access token.
   *
   * @type {string}
   */
  readonly accountId: string;

  /**
   * Property totp
   * @readonly
   *
   * @description
   * Candidate one-time code.
   *
   * @type {string}
   */
  readonly totp: string;
  // #endregion
}

/**
 * Class EnableTwoFactor
 * @class EnableTwoFactor
 *
 * @description
 * Second enrollment step (D17): under the account row lock, the code is checked against the pending
 * secret with the login's window and replay rules; a right one activates the secret. A wrong code is not
 * counted towards the lockout: the password was proven by the setup and the pending secret guards nothing yet.
 */
export class EnableTwoFactor {
  // #region Constructor
  /**
   * Constructor
   * @constructor
   *
   * @description
   * Supplies transaction, code verification and time dependencies.
   *
   * @param {IdentityUnitOfWork} unitOfWork - Transaction boundary for the account update.
   * @param {TotpVerifier} totp - Time-based code verifier.
   * @param {Clock} clock - Source of the verification time.
   */
  public constructor(
    private readonly unitOfWork: IdentityUnitOfWork,
    private readonly totp: TotpVerifier,
    private readonly clock: Clock,
  ) {}
  // #endregion

  // #region Methods
  /**
   * Method execute
   * @method execute
   *
   * @description
   * An unknown account rejects with `InvalidSessionError`; an active second factor or a missing enrollment rejects with `TwoFactorStateError`; a wrong or replayed code rejects with `TotpInvalidError` and leaves the enrollment pending.
   *
   * @param {EnableTwoFactorCommand} command - Account and code.
   *
   * @returns {Promise<void>} Completion once the second factor is on.
   */
  public async execute(command: EnableTwoFactorCommand): Promise<void> {
    const now: Date = this.clock.now();
    await this.unitOfWork.run(async ({ accounts }): Promise<void> => {
      const account: AdminAccount | null = await accounts.lockById(command.accountId);
      if (account === null) {
        throw new InvalidSessionError();
      }
      const pending: string | null = account.pendingTotpSecret;
      if (account.isTwoFactorEnabled || pending === null) {
        throw new TwoFactorStateError();
      }
      const step: number | null = this.totp.verify(pending, command.totp, now);
      if (step === null || !account.isFreshTotpStep(step)) {
        throw new TotpInvalidError();
      }
      await accounts.save(account.enableTwoFactor(step));
    });
  }
  // #endregion
}
